    tags=['m_AUDIT_SERVICE_ANNUALISED']
) }}
{{ config(materialized='table') }}
-- Self-referencing table(s): 'AUDIT_SERVICE_ANNUALISED' used as both source and target in this mapping.
-- Materialized as TABLE to snapshot source data before the target model overwrites it.
SELECT
   CURRENT_DATE() AUDIT_DATE,
   CAST('AUDIT_BET_ANNUAL_ACT_RST' AS VARCHAR(255)) AUDIT_NAME,
   'N_BKGS_MEASURE' SRC_TABLE_NAME,
   'MT_RSTD_BKGS_MEASURE' TGT_TABLE_NAME,
   CAST('ANNUAL_AMT' AS VARCHAR(255)) AMOUNT_NAME,
   ACT.DV_FISCAL_YEAR_MTH_NUMBER_INT SRC_FISCAL_YEAR_MTH_NUMBER_INT,
   ACT.BKGS_MEASURE_TRANS_TYPE_CODE AS SRC_BKGS_MEASURE_TRANS_TYPE_CD,
   ACT.BOOKINGS_PROCESS_DATE SRC_BOOKINGS_PROCESS_DATE,
   ZEROIFNULL(ACT.ANNUAL_AMT) SRC_AMT,
   RST.DV_FISCAL_YEAR_MTH_NUMBER_INT TGT_FISCAL_YEAR_MTH_NUMBER_INT,
   RST.BKGS_MEASURE_TRANS_TYPE_CODE AS TGT_BKGS_MEASURE_TRANS_TYPE_CD,
   RST.BOOKINGS_PROCESS_DATE TGT_BOOKINGS_PROCESS_DATE,
   ZEROIFNULL(RST.ANNUAL_AMT) TGT_AMT,
   ZEROIFNULL(ACT.ANNUAL_AMT) - ZEROIFNULL(RST.ANNUAL_AMT) AUDIT_AMT,
   CURRENT_USER() AS EDW_CREATE_USER,
   CURRENT_USER() AS EDW_UPDATE_USER,
   CURRENT_TIMESTAMP(0) AS EDW_CREATE_DATETIME,
   CURRENT_TIMESTAMP(0) AS EDW_UPDATE_DATETIME
FROM
   (
      SELECT
         DV_FISCAL_YEAR_MTH_NUMBER_INT,
         BKGS_MEASURE_TRANS_TYPE_CODE,
         BOOKINGS_PROCESS_DATE,
         SUM(ZEROIFNULL(DV_ANNUALIZED_US_NET_AMT)) ANNUAL_AMT
      FROM
         {{ var('m_AUDIT_SERVICE_ANNUALISED_SLSORDVWDB') }}.N_BKGS_MEASURE NBM
         INNER JOIN
            {{ var('m_AUDIT_SERVICE_ANNUALISED_COMREFVWDB') }}.R_FISCAL_DAY_TO_YEAR RDAYS
            ON NBM.BOOKINGS_PROCESS_DATE = RDAYS.CALENDAR_DATE
         INNER JOIN
            {{ var('m_AUDIT_SERVICE_ANNUALISED_COMREFVWDB') }}.R_FISCAL_MONTH_TO_YEAR RFM
            ON RFM.FISCAL_YEAR_AGE IN (1, 0)
      /*ON (
      ( RFM.PREVIOUS_FSCL_MONTH_FLAG      = 'Y' 
      AND CURRENT_DATE BETWEEN RFM.FISCAL_MONTH_END_DATE + 1 AND  RFM.FISCAL_MONTH_END_DATE + 6) 
      OR  RFM.CURRENT_FISCAL_MONTH_FLAG    = 'Y'   
      )*/
      WHERE
         RFM.FISCAL_YEAR_MONTH_INT = NBM.DV_FISCAL_YEAR_MTH_NUMBER_INT
         AND COLLATE(SERVICE_FLG, 'en-ci-rtrim') = 'Y'
      GROUP BY
         1,
         2,
         3
   ) ACT
   FULL OUTER JOIN
      (
         SELECT
            DV_FISCAL_YEAR_MTH_NUMBER_INT,
            BKGS_MEASURE_TRANS_TYPE_CODE,
            BOOKINGS_PROCESS_DATE,
            SUM(ZEROIFNULL(DV_ANNUALIZED_US_NET_AMT)) ANNUAL_AMT
         FROM
            {{ var('m_AUDIT_SERVICE_ANNUALISED_SLSORDVWDB') }}.MT_RSTD_BKGS_MEASURE NBM
            INNER JOIN
               {{ var('m_AUDIT_SERVICE_ANNUALISED_COMREFVWDB') }}.R_FISCAL_DAY_TO_YEAR RDAYS
               ON NBM.BOOKINGS_PROCESS_DATE = RDAYS.CALENDAR_DATE
            INNER JOIN
               {{ var('m_AUDIT_SERVICE_ANNUALISED_COMREFVWDB') }}.R_FISCAL_MONTH_TO_YEAR RFM
               ON RFM.FISCAL_YEAR_AGE IN (1, 0)
         /*ON (
         ( RFM.PREVIOUS_FSCL_MONTH_FLAG      = 'Y' 
         AND CURRENT_DATE BETWEEN RFM.FISCAL_MONTH_END_DATE + 1 AND  RFM.FISCAL_MONTH_END_DATE + 6) 
         OR RFM.CURRENT_FISCAL_MONTH_FLAG    = 'Y'   
         )*/
         WHERE
            RFM.FISCAL_YEAR_MONTH_INT = NBM.DV_FISCAL_YEAR_MTH_NUMBER_INT
            AND COLLATE(SERVICE_FLG, 'en-ci-rtrim') = 'Y'
         GROUP BY
            1,
            2,
            3
      ) RST
      ON RST.DV_FISCAL_YEAR_MTH_NUMBER_INT = ACT.DV_FISCAL_YEAR_MTH_NUMBER_INT
      AND RST.BKGS_MEASURE_TRANS_TYPE_CODE = ACT.BKGS_MEASURE_TRANS_TYPE_CODE
      AND RST.BOOKINGS_PROCESS_DATE = ACT.BOOKINGS_PROCESS_DATE
WHERE
   AUDIT_AMT NOT BETWEEN -4 AND 4
UNION ALL
/*AUDIT BETWEEN MY AMT IN ACTUAL TABLES  AND MY AMOUNTS RSTD TABLES*/
SELECT
