            INNER JOIN
               {{ var('m_AUDIT_SERVICE_ANNUALISED_COMREFVWDB') }}.R_FISCAL_DAY_TO_YEAR RDAYS
               ON NBM.BOOKINGS_PROCESS_DATE = RDAYS.CALENDAR_DATE
            INNER JOIN
               {{ var('m_AUDIT_SERVICE_ANNUALISED_COMREFVWDB') }}.R_FISCAL_MONTH_TO_YEAR RFM
               ON RFM.FISCAL_YEAR_AGE IN (1, 0)
         /*ON (
